import re

def parse_ini(text: str) -> dict[str, dict[str, str]]:
    """
    Parse INI text into a dictionary of sections and their key-value pairs.

    :param text: The INI text to parse
    :return: A dictionary of sections and their key-value pairs
    """

    sections = {}
    default_section = {}

    current_section = None

    for line in text.splitlines():
        # Ignore lines that are empty or whose first non-space character is a comment
        line = line.strip()
        if not line or line.startswith((';', '#')):
            continue

        # Check for section headers
        if line.startswith('[') and line.endswith(']'):
            section_name = line[1:-1].strip()
            if section_name == 'DEFAULT':
                current_section = default_section
            else:
                current_section = sections.setdefault(section_name, {})
            continue

        # If we haven't seen a section header yet, raise ValueError
        if current_section is None:
            raise ValueError("Key line before any section header")

        # Split the line into key and value
        match = re.match(r'([^:=]+)[:=](.*)', line)
        if not match:
            raise ValueError("Malformed line")
        key, value = match.groups()
        key = key.strip().lower()

        # Handle continuation lines
        while True:
            next_line = text.splitlines()[text.splitlines().index(line) + 1].strip()
            if next_line and next_line.startswith(' '):
                value += '\n' + next_line.strip()
                text = text.replace(next_line, '', 1)
            else:
                break

        # Remove inline comments and double quotes
        value = re.sub(r'(;| #).*$', '', value)
        if value.startswith('"') and value.endswith('"'):
            value = value[1:-1]
        else:
            value = value.strip()

        # Store the key-value pair
        current_section[key] = value

    # Interpolate values
    for section_name, section in sections.items():
        for key, value in section.items():
            while True:
                match = re.search(r'\${([^:]+)(:[^}]+)?}', value)
                if not match:
                    break
                ref_key, ref_section = match.groups()
                if ref_section:
                    ref_section = ref_section[1:]
                else:
                    ref_section = section_name
                ref_section_data = sections.get(ref_section, default_section)
                ref_value = ref_section_data.get(ref_key)
                if ref_value is None:
                    raise KeyError(f"Missing key {ref_key}")
                if ref_value == value:
                    raise ValueError("Reference cycle")
                value = value.replace(match.group(0), ref_value, 1)

    # Inherit DEFAULT section keys
    for section in sections.values():
        section.update({k: v for k, v in default_section.items() if k not in section})

    return sections
