from collections import OrderedDict
from typing import Callable, Dict, Optional

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock: Callable[[], float]):
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self.cache = OrderedDict()
        self.stats = {"hits": 0, "misses": 0, "evictions": 0, "expirations": 0}

    def put(self, key, value):
        now = self.clock()
        if key in self.cache:
            del self.cache[key]
        elif self.capacity > 0 and len(self.cache) >= self.capacity:
            self._remove_expired(now)
            if len(self.cache) >= self.capacity:
                self.cache.popitem(last=False)
                self.stats["evictions"] += 1
        self.cache[key] = (value, now + self.ttl)

    def get(self, key, default=None):
        now = self.clock()
        if key in self.cache:
            value, expiry = self.cache[key]
            if expiry > now:
                self.cache.move_to_end(key)
                self.stats["hits"] += 1
                return value
            else:
                del self.cache[key]
                self.stats["expirations"] += 1
        self.stats["misses"] += 1
        return default

    def __len__(self):
        now = self.clock()
        self._remove_expired(now)
        return len(self.cache)

    def stats(self) -> Dict[str, int]:
        return self.stats.copy()

    def _remove_expired(self, now: float):
        while self.cache and self.cache[next(reversed(self.cache))][1] <= now:
            del self.cache[next(reversed(self.cache))]
            self.stats["expirations"] += 1
