import re
from enum import Enum
from typing import Match

class Unit(Enum):
    HOURS = 1
    MINUTES = 2
    SECONDS = 3

    @property
    def value(self):
        return {
            Unit.HOURS: 3600,
            Unit.MINUTES: 60,
            Unit.SECONDS: 1,
        }.get(self)

    @classmethod
    def from_str(cls, s: str) -> 'Unit':
        s = s.lower()
        if s == 'h':
            return cls.HOURS
        elif s == 'm':
            return cls.MINUTES
        elif s == 's':
            return cls.SECONDS
        else:
            raise ValueError(f"Unknown unit: {s}")


def parse_duration(s: str) -> int:
    """
    Convert a duration string into a total number of seconds.

    :param s: A duration string.
    :return: The total number of seconds.
    :raises ValueError: If the input string is invalid.
    """

    # Remove whitespace and normalize to lowercase
    s = re.sub(r'\s+', '', s).lower()

    # Check for empty/blank strings
    if not s:
        raise ValueError("Empty string")

    # Parse each part of the duration
    parts = re.findall(r'(\d+)([hms])', s)
    if len(parts)!= len(s):
        raise ValueError("Invalid duration string")

    # Validate the order and uniqueness of units
    units = [Unit.from_str(unit) for _, unit in parts]
    if units!= sorted(units):
        raise ValueError("Units are out of order")
    if len(set(units))!= len(units):
        raise ValueError("Repeated units")

    # Convert the duration to seconds
    total_seconds = 0
    for value, unit in parts:
        total_seconds += int(value) * Unit.from_str(unit).value

    return total_seconds
